        setTimeLeft(prev => ({ ...prev, sec: prev.sec - 1 }));
      } else if (timeLeft.min > 0) {
        setTimeLeft(prev => ({ min: prev.min - 1, sec: 59 }));
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const formatTime = (t: number) => t < 10 ? `0${t}` : t;

