const Countdown = () => {
  const [time, setTime] = useState(899);
  useEffect(() => {
    const i = setInterval(() => setTime(t => t > 0 ? t - 1 : 0), 1000);
    return () => clearInterval(i);
  }, []);
  const m = Math.floor(time / 60);
  const s = time % 60;
  return (
    <div className="inline-flex items-center gap-2 bg-orange-600/10 text-orange-700 px-5 py-2.5 rounded-2xl border border-orange-600/20 font-black text-sm tracking-tight">
      <Timer size={18} className="animate-spin-slow" />
      <span>OFERTA EXPIRA EM {m}:{s < 10 ? `0${s}` : s}</span>
    </div>
  );
};

